#[target_feature(enable = "avx512f,avx2")]
fn test_x86_avx512f_mm256_mask_shuffle_epi32_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("avx2")) {
            return Ok(Verdict::Skipped("avx2 not present"));
        }
    unsafe {
        let a = create__m256i_from_i32_array([1, 2, 3, 4, 5, 6, 7, 8]);
        let src = create__m256i_from_i32_array([9, 10, 11, 12, 13, 14, 15, 16]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m256i_to_i32_array(_mm256_mask_shuffle_epi32::<0>(src, k, a));
        let plain = unpack__m256i_to_i32_array(_mm256_shuffle_epi32::<0>(a));
        let src_lanes = unpack__m256i_to_i32_array(src);
        let expected: [i32; 8] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm256_mask_shuffle_epi32::<0>(src, k, a) vs _mm256_shuffle_epi32::<0>(a)"))?;
        Ok(Verdict::Checked)
    }
}

