#[target_feature(enable = "avx512f,avx2")]
fn test_x86_avx512f_mm256_maskz_shuffle_epi32_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("avx2")) {
            return Ok(Verdict::Skipped("avx2 not present"));
        }
    unsafe {
        let a = create__m256i_from_i32_array([1, 2, 3, 4, 5, 6, 7, 8]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m256i_to_i32_array(_mm256_maskz_shuffle_epi32::<0>(k, a));
        let plain = unpack__m256i_to_i32_array(_mm256_shuffle_epi32::<0>(a));
        let expected: [i32; 8] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { 0 });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm256_maskz_shuffle_epi32::<0>(k, a) vs _mm256_shuffle_epi32::<0>(a)"))?;
        Ok(Verdict::Checked)
    }
}

