#[target_feature(enable = "avx512f,sse2")]
fn test_x86_avx512f_mm_mask_shuffle_epi32_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("sse2")) {
            return Ok(Verdict::Skipped("sse2 not present"));
        }
    unsafe {
        let a = create__m128i_from_i32_array([1, 2, 3, 4]);
        let src = create__m128i_from_i32_array([5, 6, 7, 8]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m128i_to_i32_array(_mm_mask_shuffle_epi32::<0>(src, k, a));
        let plain = unpack__m128i_to_i32_array(_mm_shuffle_epi32::<0>(a));
        let src_lanes = unpack__m128i_to_i32_array(src);
        let expected: [i32; 4] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm_mask_shuffle_epi32::<0>(src, k, a) vs _mm_shuffle_epi32::<0>(a)"))?;
        Ok(Verdict::Checked)
    }
}

