#[target_feature(enable = "avx512f,avx")]
fn test_x86_avx512f_mm256_maskz_shuffle_pd_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("avx")) {
            return Ok(Verdict::Skipped("avx not present"));
        }
    unsafe {
        let a = create__m256d_from([1.0, 2.0, 3.0, 4.0]);
        let b = create__m256d_from([5.0, 6.0, 7.0, 8.0]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m256d_to_f64_array(_mm256_maskz_shuffle_pd::<0>(k, a, b));
        let plain = unpack__m256d_to_f64_array(_mm256_shuffle_pd::<0>(a, b));
        let expected: [f64; 4] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { 0.0 });
        check_float_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm256_maskz_shuffle_pd::<0>(k, a, b) vs _mm256_shuffle_pd::<0>(a, b)"))?;
        Ok(Verdict::Checked)
    }
}

