#[target_feature(enable = "avx512f,sse2")]
fn test_x86_avx512f_mm_mask_shuffle_pd_vs_unmasked_impl() -> Result<Verdict, String> {
        if !(std::arch::is_x86_feature_detected!("sse2")) {
            return Ok(Verdict::Skipped("sse2 not present"));
        }
    unsafe {
        let a = create__m128d_from([1.0, 2.0]);
        let b = create__m128d_from([3.0, 4.0]);
        let src = create__m128d_from([5.0, 6.0]);
        let k = create__mmask8_from(0b01010101);
        let masked = unpack__m128d_to_f64_array(_mm_mask_shuffle_pd::<0>(src, k, a, b));
        let plain = unpack__m128d_to_f64_array(_mm_shuffle_pd::<0>(a, b));
        let src_lanes = unpack__m128d_to_f64_array(src);
        let expected: [f64; 2] = core::array::from_fn(|i| if (k >> i) & 1 == 1 { plain[i] } else { src_lanes[i] });
        check_float_array_equality(&masked, &expected).map_err(|e| crate::cpu::with_call(e, "_mm_mask_shuffle_pd::<0>(src, k, a, b) vs _mm_shuffle_pd::<0>(a, b)"))?;
        Ok(Verdict::Checked)
    }
}

